<?php
namespace App\Services;
use Dompdf\Dompdf;
use Dompdf\Options;
final class PdfService {
    private static function title(string $type): string { return ['invoice'=>'FAKTURA','offer'=>'NABÍDKA','order'=>'OBJEDNÁVKA','proforma'=>'ZÁLOHOVÁ FAKTURA','credit'=>'DOBROPIS'][$type] ?? 'DOKLAD'; }
    private static function normalizeIban(string $value):?string{
        $v=strtoupper(preg_replace('/\s+/','',trim($value))); if($v==='')return null;
        if(preg_match('/^CZ[0-9]{22}$/',$v)){ $check=substr($v,2,2);$bban=substr($v,4);$num=$bban.'1235'.$check;$rem=0;for($i=0,$n=strlen($num);$i<$n;$i++)$rem=(($rem*10)+(int)$num[$i])%97;return $rem===1?$v:null; }
        if(preg_match('/^(?:(\d{1,10})-)?(\d{1,10})\/(\d{4})$/',$v,$m)){ $prefix=str_pad($m[1]??'',6,'0',STR_PAD_LEFT);$account=str_pad($m[2],10,'0',STR_PAD_LEFT);$bban=$m[3].$prefix.$account;$num=$bban.'123500';$rem=0;for($i=0,$n=strlen($num);$i<$n;$i++)$rem=(($rem*10)+(int)$num[$i])%97;return 'CZ'.str_pad((string)(98-$rem),2,'0',STR_PAD_LEFT).$bban; }
        return null;
    }
    public static function invoice(array $doc,array $items,array $company,array $customer,?string $qrUrl=null): string {
        $esc=fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8'); $rows='';
        foreach($items as $i=>$it)$rows.='<tr><td>'.($i+1).'</td><td>'.$esc($it['name']).'</td><td>'.$esc($it['quantity']).' '.$esc($it['unit']).'</td><td>'.number_format((float)$it['unit_price'],2,',',' ').'</td><td>'.number_format((float)$it['line_total'],2,',',' ').'</td></tr>';
        $logoHtml=''; if(!empty($company['logo_path'])){ $logoFile=dirname(__DIR__,2).'/'.ltrim((string)$company['logo_path'],'/'); if(is_file($logoFile)){ $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($logoFile); if(in_array($mime,['image/png','image/jpeg','image/svg+xml'],true))$logoHtml='<img src="data:'.$mime.';base64,'.base64_encode((string)file_get_contents($logoFile)).'" style="max-width:180px;max-height:58px;object-fit:contain;margin-bottom:8px" alt="Logo">'; }}
        $qrHtml=''; $iban=self::normalizeIban((string)($company['bank_account']??''));
        if($iban && (($doc['doc_type']??'')==='invoice')){ $spayd='SPD*1.0*ACC:'.$iban.'*AM:'.number_format((float)$doc['total_with_vat'],2,'.','').'*CC:CZK*X-VS:'.($doc['variable_symbol']??''); try{ if(class_exists('Endroid\\QrCode\\QrCode')){ $qr=\Endroid\QrCode\QrCode::create($spayd)->setSize(220)->setMargin(8);$result=(new \Endroid\QrCode\Writer\PngWriter())->write($qr);$src='data:'.$result->getMimeType().';base64,'.base64_encode($result->getString());$link=$qrUrl?'<a href="'.$esc($qrUrl).'">':'';$end=$qrUrl?'</a>':'';$qrHtml='<div style="margin-top:28px;text-align:right"><div style="font-weight:800;margin-bottom:6px">QR PLATBA</div>'.$link.'<img src="'.$src.'" style="width:135px;height:135px" alt="QR platba">'.$end.'<div class="muted" style="font-size:10px;margin-top:5px">Kliknutím otevřete QR platbu</div></div>'; }}catch(\Throwable $e){} }
        $html='<!doctype html><html lang="cs"><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#18243b;font-size:11px;margin:34px}.top{display:flex;justify-content:space-between;gap:35px;padding-bottom:20px;border-bottom:2px solid #dce7f5}.brand{width:54%}.supplier{width:46%;text-align:right;line-height:1.55}.logo{max-width:180px;max-height:52px;object-fit:contain;margin-bottom:8px}.eyebrow{font-size:10px;letter-spacing:1.2px;color:#6b7b91;font-weight:700;text-transform:uppercase}.title{font-size:29px;line-height:1.05;font-weight:800;margin:5px 0}.number{font-size:12px;color:#5f6f85}.grid{display:flex;gap:18px;margin:24px 0}.box{flex:1;background:#f7f9fc;border:1px solid #e4eaf2;border-radius:12px;padding:15px;line-height:1.55}.box b{display:block;margin-bottom:6px;color:#53647a}.meta{background:#fff}.tablebox{border:1px solid #e1e7ef;border-radius:12px;overflow:hidden}table{width:100%;border-collapse:collapse}th{background:#102a54;color:#fff;text-align:left;padding:10px;font-size:10px}td{border-bottom:1px solid #e8edf3;padding:10px}tr:last-child td{border-bottom:0}.totalrow{display:flex;justify-content:flex-end;margin-top:18px}.total{width:285px;border:1px solid #e1e7ef;border-radius:12px;padding:13px}.line{display:flex;justify-content:space-between;padding:5px 0;color:#5d6c80}.grand{display:flex;justify-content:space-between;border-top:2px solid #102a54;margin-top:7px;padding-top:10px;font-size:17px;font-weight:800;color:#102a54}.bottom{display:flex;justify-content:space-between;gap:24px;margin-top:20px}.payment{flex:1;padding:14px;background:#f7f9fc;border-radius:12px;border:1px solid #e4eaf2}.qr{width:170px;text-align:center}.qr img{width:145px;height:145px}.muted{color:#758399;font-size:9px}.footer{margin-top:28px;padding-top:12px;border-top:1px solid #e5eaf1;color:#7a8798;font-size:9px}</style><div class="top"><div class="brand">'.$logoHtml.'<div class="eyebrow">Doklad</div><div class="title">'.$esc(self::title($doc['doc_type']??'invoice')).'</div><div class="number">Číslo '.$esc($doc['doc_number']).'</div></div><div class="supplier"><b>'.$esc($company['name']??'').'</b><br>'.$esc($company['street']??'').'<br>'.$esc(($company['zip']??'').' '.($company['city']??'')).'<br>IČO '.$esc($company['ico']??'').'</div></div><div class="grid"><div class="box"><b>Odběratel</b>'.$esc($customer['company_name']??trim(($customer['first_name']??'').' '.($customer['last_name']??''))).'<br>'.$esc($customer['street']??'').'<br>'.$esc(($customer['zip']??'').' '.($customer['city']??'')).'</div><div class="box meta"><b>Datum a platba</b>Vystaveno: '.$esc($doc['issue_date']).'<br>Splatnost: '.$esc($doc['due_date']).'<br>Variabilní symbol: '.$esc($doc['variable_symbol']).'</div></div><div class="tablebox"><table><thead><tr><th>#</th><th>Položka</th><th>Množství</th><th>Jedn. cena</th><th>Celkem</th></tr></thead><tbody>'.$rows.'</tbody></table></div><div class="totalrow"><div class="total"><div class="line"><span>Bez DPH</span><b>'.number_format((float)$doc['total_without_vat'],2,',',' ').' Kč</b></div><div class="line"><span>DPH</span><b>'.number_format((float)$doc['total_vat'],2,',',' ').' Kč</b></div><div class="grand"><span>K úhradě</span><span>'.number_format((float)$doc['total_with_vat'],2,',',' ').' Kč</span></div></div></div><div class="bottom"><div class="payment"><b>Platební údaje</b><br>Částka: '.number_format((float)$doc['total_with_vat'],2,',',' ').' Kč<br>Variabilní symbol: '.$esc($doc['variable_symbol']).'</div>'.$qrHtml.'</div><div class="footer">Dokument vytvořen systémem Byznio.</div></html>';
        $o=new Options();$o->set('defaultFont','DejaVu Sans');$o->set('isRemoteEnabled',false);$d=new Dompdf($o);$d->loadHtml($html,'UTF-8');$d->setPaper('A4');$d->render();return $d->output();
    }
}
